package com.mfg.mdm.controller;
import com.mfg.common.api.ApiResponse;import com.mfg.mdm.service.MdmGovernanceService;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/mdm") @RequiredArgsConstructor public class MdmGovernanceController{private final MdmGovernanceService service;
 @GetMapping("/{type:warehouses|work-centers|production-versions}")public ApiResponse<Page<Map<String,Object>>>page(@PathVariable String type,@RequestParam(required=false)String keyword,@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(service.page(type,keyword,status,page,size));}
 @PostMapping("/{type:warehouses|work-centers|production-versions}")public ApiResponse<Map<String,Object>>create(@PathVariable String type,@RequestBody Map<String,Object>x){return ApiResponse.ok(service.save(type,null,x));}@PutMapping("/{type:warehouses|work-centers|production-versions}/{id}")public ApiResponse<Map<String,Object>>update(@PathVariable String type,@PathVariable Long id,@RequestBody Map<String,Object>x){return ApiResponse.ok(service.save(type,id,x));}@DeleteMapping("/{type:warehouses|work-centers|production-versions}/{id}")public ApiResponse<Void>disable(@PathVariable String type,@PathVariable Long id){service.disable(type,id);return ApiResponse.ok();}
 @GetMapping("/{partnerType:customers|suppliers}/{partnerId}/contacts")public ApiResponse<List<Map<String,Object>>>contacts(@PathVariable String partnerType,@PathVariable Long partnerId){return ApiResponse.ok(service.contacts(partnerType.startsWith("customer")?"CUSTOMER":"SUPPLIER",partnerId));}@PostMapping("/{partnerType:customers|suppliers}/{partnerId}/contacts")public ApiResponse<Map<String,Object>>createContact(@PathVariable String partnerType,@PathVariable Long partnerId,@RequestBody Map<String,Object>x){return ApiResponse.ok(service.saveContact(partnerType.startsWith("customer")?"CUSTOMER":"SUPPLIER",partnerId,null,x));}@PutMapping("/{partnerType:customers|suppliers}/{partnerId}/contacts/{id}")public ApiResponse<Map<String,Object>>updateContact(@PathVariable String partnerType,@PathVariable Long partnerId,@PathVariable Long id,@RequestBody Map<String,Object>x){return ApiResponse.ok(service.saveContact(partnerType.startsWith("customer")?"CUSTOMER":"SUPPLIER",partnerId,id,x));}@DeleteMapping("/{partnerType:customers|suppliers}/{partnerId}/contacts/{id}")public ApiResponse<Void>deleteContact(@PathVariable String partnerType,@PathVariable Long partnerId,@PathVariable Long id){service.deleteContact(partnerType.startsWith("customer")?"CUSTOMER":"SUPPLIER",partnerId,id);return ApiResponse.ok();}
 @PostMapping("/merge")public ApiResponse<Map<String,Object>>merge(@RequestBody Map<String,Object>x){return ApiResponse.ok(service.merge(x));}@GetMapping("/governance/{kind:merges|mappings|history}")public ApiResponse<Page<Map<String,Object>>>governance(@PathVariable String kind,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(service.governance(kind,page,size));}}
